@using sv_cadf64d755c540d087d939a1362ae3c3.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme -->
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Light" @onchange="() => _theme = &quot;Light&quot;" checked="@(_theme == "Light")" />
                        <span>Light</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="Dark" @onchange="() => _theme = &quot;Dark&quot;" checked="@(_theme == "Dark")" />
                        <span>Dark</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="theme" value="System" @onchange="() => _theme = &quot;System&quot;" checked="@(_theme == "System")" />
                        <span>System</span>
                    </label>
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Small" @onchange="() => _fontSize = &quot;Small&quot;" checked="@(_fontSize == "Small")" />
                        <span>Small</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Medium" @onchange="() => _fontSize = &quot;Medium&quot;" checked="@(_fontSize == "Medium")" />
                        <span>Medium</span>
                    </label>
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="Large" @onchange="() => _fontSize = &quot;Large&quot;" checked="@(_fontSize == "Large")" />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <h3>Language</h3>
                <select @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <p>Theme: <strong>@_theme</strong> | Font: <strong>@_fontSize</strong> | Language: <strong>@GetLanguageName()</strong></p>
                @if (_compactMode)
                {
                    <p><em>Compact mode is enabled — reduced spacing and smaller elements.</em></p>
                }
            </div>

            <div class="form-actions">
                <button class="btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private string GetLanguageName() => _language switch
    {
        "en" => "English",
        "es" => "Spanish",
        "fr" => "French",
        "de" => "German",
        "ja" => "Japanese",
        "zh" => "Chinese",
        _ => _language
    };

    private async Task SaveAppearance()
    {
        _saving = true;
        _showSuccess = false;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _showSuccess = true;

        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

arguments.file_text:
.settings-layout {
    display: flex;
    min-height: 80vh;
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 200px;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.2s;
    margin-bottom: 0.25rem;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar li.active {
    background-color: #e3f2fd;
    color: #1565c0;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.2rem;
}

/* Content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    border-bottom: 1px solid #e0e0e0;
    padding-bottom: 0.75rem;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn-primary {
    background-color: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover:not(:disabled) {
    background-color: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background-color: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-secondary:hover {
    background-color: #e0e0e0;
}

.btn-danger {
    background-color: #d32f2f;
    color: white;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-danger:hover {
    background-color: #b71c1c;
}

.btn-small {
    padding: 0.3rem 0.7rem;
    font-size: 0.8rem;
}

/* Toast messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

.toast.success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast.error {
    background-color: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

/* Toggle items */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: #666;
    margin-top: 0.3rem;
    word-break: break-all;
}

/* Channels section */
.channels-section {
    margin-top: 1.5rem;
}

.channels-section h3 {
    margin-bottom: 0.75rem;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
