    background-color: #f5f5f5;
    color: #333;
}

.preview-font-small {
    font-size: 0.85rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.75rem;
